(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(y*0.012+t*0.2)*20 + Math.cos(x*0.008-t*0.15)*15;
  const w1y = Math.cos(x*0.013-t*0.18)*18 + Math.sin(y*0.009+t*0.22)*14;
  const w2x = Math.sin((x+y)*0.006+t*0.1)*12;
  const w2y = Math.cos((x-y)*0.007-t*0.12)*12;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [120+Math.sin(t*0.5)*100, 80+Math.cos(t*0.35)*60, 0.07, 2.2],
    [360+Math.cos(t*0.45)*110, 160+Math.sin(t*0.55)*70, 0.09, 1.8],
    [240+Math.sin(t*0.3+2)*150, 60+Math.cos(t*0.4+1)*80, 0.055, 2.5],
    [80+Math.cos(t*0.7+1)*70, 200+Math.sin(t*0.5+3)*50, 0.11, 1.6],
    [400+Math.sin(t*0.35+4)*80, 40+Math.cos(t*0.8+2)*60, 0.065, 2.8],
    [200+Math.cos(t*0.3+5)*130, 220+Math.sin(t*0.45)*70, 0.08, 2.0],
    [300+Math.sin(t*0.6+3)*90, 100+Math.cos(t*0.5+4)*80, 0.075, 2.3],
    [160+Math.cos(t*0.4+2)*110, 150+Math.sin(t*0.65+1)*60, 0.1, 1.5]
  ];
  let aS=0,iS=0,aH=0,iH=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2=Math.sqrt((sx*0.5-sX*0.5)**2+(sy*0.5-sY*0.5)**2);
    aS+=Math.sin(d*f-t*sp); iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aH+=Math.sin(d2*f*1.4-t*sp*0.8+0.5); iH+=Math.cos(d2*f*1.1+t*sp*0.5+2.0);
  }
  const n=src.length, act=aS/n, inh=iS/n, actH=aH/n, inhH=iH/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.05+sy*0.01-t*0.6))/3
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.02+t*0.4)*Math.sin(sy*0.03-t*0.3)*0.3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.06-ang*2+t*0.8))*0.333;
  const radial=Math.sin(dist*0.08-t*2)*0.3;
  const cs=0.12, cX=sx*cs, cY=sy*cs;
  const ci=Math.floor(cX), cj=Math.floor(cY);
  let minD=999;
  for(let di=-1;di<=1;di++)for(let dj=-1;dj<=1;dj++){
    const nx=ci+di,ny=cj+dj;
    const px=nx+Math.sin(nx*1.7+ny*2.3+t*0.5)*0.4+Math.cos(nx*3.1-ny*1.1+t*0.3)*0.3;
    const py=ny+Math.cos(nx*2.1+ny*1.9-t*0.4)*0.4+Math.sin(nx*1.3-ny*2.7+t*0.6)*0.3;
    const d=Math.sqrt((cX-px)**2+(cY-py)**2);
    if(d<minD)minD=d;
  }
  const cell=Math.tanh((minD-0.35)*4)*0.5;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((actH-inhH*0.6+bg*0.2+radial)*1.8);
  const coupled=r1*0.7+r2*0.3;
  const edgeMask=1.0-Math.abs(cell)*0.5;
  const blend=coupled*0.7+cell*0.2+radial*0.1;
  const v=Math.tanh(blend*1.5)*0.5+0.5;
  const pal=[[6,12,58],[12,45,95],[18,90,120],[25,140,130],[140,190,100],[220,195,60],[230,140,55],[210,85,65],[170,45,60],[100,25,55],[50,15,55],[6,12,58]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(coupled*Math.PI)*0.15+Math.abs(cell)*0.1;
  const edge=Math.abs(coupled)>0.75?1.12:1.0;
  const m=lum*edge*edgeMask;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*m)|0
  ];
}
